layer.css:
[data-ryt="pitch"] { color: var(--ryt-muted); background-color: rgba(255, 255, 255, 0.01); border-left: 3px solid rgb(255, 140, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; padding-top: 10px; padding-right: 20px; padding-bottom: 10px; padding-left: 40px; transition: all; border-top: none; border-right: none; border-bottom: none; position: relative }
article[data-ryt="rec-card"] { border-bottom: 1px dashed rgb(77, 54, 0); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; transition: all }
[data-ryt="brand"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 2.4px, var(--ryt-text) 0px 0px 4.8px, var(--ryt-text) 0px 0px 8px; transition: all }
[data-ryt="header"] { border-bottom: 1px solid rgb(77, 54, 0); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: 0.9px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; padding-top: 10px; padding-right: 0px; padding-bottom: 10px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 2.4px, var(--ryt-text) 0px 0px 4.8px, var(--ryt-text) 0px 0px 8px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a::before { content: "\3e  "; display: inline; color: var(--ryt-muted); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-muted) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #ffd966 }
[data-ryt="nav"] a::before { content: "[ "; display: inline; color: var(--ryt-muted); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: 0.9px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-muted) }
[data-ryt="nav"] a::after { content: " ]"; display: inline; color: var(--ryt-muted); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: 0.9px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-muted) }
[data-ryt="nav"] a:hover { color: #ffd966; color: #ffd966 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #ffd966; color: #ffd966 }
[data-ryt="pitch"]::before { content: "\3e \3e "; display: block; position: absolute; width: 20px; height: 32px; color: rgb(255, 140, 0); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 140, 0); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-text) 0px 0px 1.6px, var(--ryt-text) 0px 0px 3.2px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(255, 140, 0); top: 10px; left: 10px }
